// glass-ui 10.1.5 — critic round 11's probe harness. Reads only. The v1014 arm is this file with its
// imports pointed at `v1014/` (generated by sed, critic-11-v1014.ts).
// Scenes:
//   `o205`   INBOUND O-205: daraksha's one dock, fit-content, `?collapse=closed|false`, a persistent khatam,
//            the default slot a `DockLayerGroup :show-switcher="false"` of two faces (`?layers=1`, the
//            active `?active=read|pages`; `read` four icon seats with one word, `pages` six worded tabs,
//            wider), or a plain run of the `read` seats (`?layers=0`).
//   `o201`   INBOUND O-201: value's dock shape, a DockLayerGroup whose face holds the Home ⌃ select trigger
//            (icon + label + chevron) at the run's start or end (`?at=start|end`), two icon controls and
//            a DarkModeToggle; `?maxw=` caps the dock.
//   `focus`  INBOUND O-207 G3: value's palette-card disclosure trigger (a CollapsibleTrigger as-child over
//            a Button with `focus-ring` and `palette-card`), a bare `.focus-ring` div, a Button, an
//            AccordionTrigger, a Checkbox, a Switch, an Input, SegmentedTabs.
//   `card`   INBOUND O-207 G1: a default scrubber Slider on a saturated card, `?ink=fg` sets value's
//            `--slider-range-bg: var(--foreground)`.
//   `fourier` INBOUND O-207 G10: fourier's AppDock shape (popover logo trigger, separator, the nav
//            dropdown trigger with icon, label and chevron, separator, two controls, separator, the
//            DarkModeToggle) in a centred header, `collapse=false`; the box is traced from mount.
// `?dark=1`, `?dir=rtl` set theme and direction.
import "../../demo/demo.css";
import { createApp, defineComponent, h, ref, type Component } from "vue";

import GlassDock from "../../src/components/dock/GlassDock.vue";
import DockControl from "../../src/components/dock/DockControl.vue";
import DockTrigger from "../../src/components/dock/DockTrigger.vue";
import DockLayerGroup from "../../src/components/dock/DockLayerGroup.vue";
import DockLayer from "../../src/components/dock/DockLayer.vue";
import DockSeparator from "../../src/components/dock/DockSeparator.vue";
import DarkModeToggle from "../../src/components/dark-mode-toggle/DarkModeToggle.vue";
import { Select, SelectContent, SelectItem, SelectValue } from "../../src/components/select";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem } from "../../src/components/menu";
import { Popover, PopoverContent } from "../../src/components/popover";
import Slider from "../../src/components/slider/Slider.vue";
import Button from "../../src/components/button/Button.vue";
import { Collapsible, CollapsibleTrigger, CollapsibleContent } from "../../src/components/collapsible";
import { Accordion, AccordionItem, AccordionTrigger, AccordionContent } from "../../src/components/accordion";
import Checkbox from "../../src/components/checkbox/Checkbox.vue";
import Switch from "../../src/components/switch/Switch.vue";
import Input from "../../src/components/input/Input.vue";
import SegmentedTabs from "../../src/components/tabs/SegmentedTabs.vue";

const params = new URLSearchParams(location.search);
const scene = params.get("scene") ?? "";
const w = window as unknown as Record<string, unknown>;
if (params.get("dir")) document.documentElement.dir = params.get("dir")!;
try {
    localStorage.setItem("vueuse-color-scheme", params.get("dark") === "1" ? "dark" : "light");
} catch {}
if (params.get("dark") === "1") document.documentElement.classList.add("dark");

const glyph = () =>
    h("svg", { viewBox: "0 0 24 24", width: 24, height: 24, "aria-hidden": "true" }, [
        h("circle", { cx: 12, cy: 12, r: 8, fill: "none", stroke: "currentColor", "stroke-width": 2 }),
    ]);
const icon = (label: string, i: number, current = false) =>
    h(DockControl, { "aria-label": label, "data-witness": `S${i}`, "aria-current": current ? "page" : undefined }, glyph);
const tab = (label: string, i: number, current = false) =>
    h(DockControl, { shape: "tab", "data-witness": `T${i}`, "aria-current": current ? "page" : undefined }, () => [glyph(), h("span", label)]);

const readSeats = () => [icon("Name", 1), tab("Colour", 2, true), icon("Motion", 3), icon("Quran", 4)];
const pageSeats = () => ["Opening", "The Cow", "Family of Imran", "The Women", "The Table", "The Cattle"].map((l, i) => tab(l, i + 1, i === 0));

const scenes: Record<string, Component> = {
    o205: defineComponent(() => {
        const active = ref(params.get("active") ?? "read");
        w.__setActive = (v: string) => (active.value = v);
        const layers = params.get("layers") !== "0";
        return () =>
            h("div", { "data-witness": "stage", style: "display:flex;justify-content:center;align-items:flex-start;padding:16px 8px;min-block-size:240px" }, [
                h(
                    GlassDock,
                    {
                        fitContent: true,
                        collapse: params.get("collapse") === "false" ? false : "closed",
                        ref: (d: unknown) => (w.__dock = d),
                    },
                    {
                        persistent: () => h(DockControl, { "aria-label": "Khatam", "data-witness": "P1" }, glyph),
                        collapsed: () => h("span", { "data-witness": "glyph" }, glyph()),
                        default: () =>
                            layers
                                ? h(
                                      DockLayerGroup,
                                      { active: active.value, "onUpdate:active": (v: string) => (active.value = v), showSwitcher: false },
                                      () => [
                                          h(DockLayer, { id: "read", label: "Read" }, readSeats),
                                          h(DockLayer, { id: "pages", label: "Pages" }, pageSeats),
                                      ],
                                  )
                                : readSeats(),
                    },
                ),
            ]);
    }),

    o201: defineComponent(() => {
        const view = ref("home");
        const home = () =>
            h(Select, { modelValue: view.value, "onUpdate:modelValue": (v: string) => (view.value = v) }, () => [
                h(DockTrigger, { for: "select", "aria-label": "Select view", "data-witness": "home" }, () => [
                    glyph(),
                    h(SelectValue, null, () => "Home"),
                ]),
                h(SelectContent, null, () => ["home", "browse", "palettes"].map((v) => h(SelectItem, { value: v }, () => v))),
            ]);
        const others = () => [icon("Undo", 1), icon("Redo", 2), h(DarkModeToggle, { size: "dock", "data-witness": "mode" })];
        return () =>
            h("div", { "data-witness": "stage", style: "display:flex;justify-content:center;align-items:flex-start;padding:16px 0;min-block-size:240px" }, [
                h(
                    GlassDock,
                    {
                        fitContent: true,
                        collapse: false,
                        style: params.get("maxw") ? `max-inline-size:${params.get("maxw")}px` : undefined,
                        ref: (d: unknown) => (w.__dock = d),
                    },
                    {
                        collapsed: () => h("span", glyph()),
                        default: () =>
                            h(DockLayerGroup, { active: "main", showSwitcher: false }, () => [
                                h(DockLayer, { id: "main", label: "Main" }, () =>
                                    params.get("at") === "end" ? [...others(), home()] : [home(), ...others()],
                                ),
                                h(DockLayer, { id: "edit", label: "Edit" }, () => [icon("Save", 8), icon("Cancel", 9)]),
                            ]),
                    },
                ),
            ]);
    }),

    focus: defineComponent(() => () =>
        h("div", { "data-witness": "stage", style: "display:grid;gap:20px;padding:24px;max-inline-size:520px" }, [
            h(Collapsible, null, () => [
                h(CollapsibleTrigger, { asChild: true }, () =>
                    h(Button, { class: "palette-card", "data-witness": "card-trigger" }, () => "Colors of Daraksha"),
                ),
                h(CollapsibleContent, null, () => "body"),
            ]),
            h(Collapsible, null, () => [
                h(CollapsibleTrigger, { class: "focus-ring", "data-witness": "plain-trigger" }, () => "Plain disclosure"),
                h(CollapsibleContent, null, () => "body"),
            ]),
            h("div", { class: "focus-ring", tabindex: 0, "data-witness": "div", style: "padding:12px;border-radius:12px;background:var(--card)" }, "focus-ring div"),
            h(Button, { "data-witness": "button" }, () => "Button"),
            h(Accordion, { type: "single", collapsible: true }, () =>
                h(AccordionItem, { value: "a" }, () => [h(AccordionTrigger, { "data-witness": "accordion" }, () => "Accordion"), h(AccordionContent, null, () => "body")]),
            ),
            h(Checkbox, { "data-witness": "checkbox", "aria-label": "check" }),
            h(Switch, { "data-witness": "switch", "aria-label": "switch" }),
            h(Input, { "data-witness": "input", placeholder: "Search" }),
            h(SegmentedTabs, { "data-witness": "tabs", modelValue: "a", options: [{ value: "a", label: "One" }, { value: "b", label: "Two" }] }),
        ]),
    ),

    card: defineComponent(() => {
        const v = ref([Number(params.get("v") ?? 40)]);
        return () =>
            h("div", { style: "padding:24px" }, [
                h(
                    "div",
                    {
                        "data-witness": "card",
                        style: `padding:24px;border-radius:24px;background:${params.get("bg") ?? "oklch(0.62 0.2 25)"};${params.get("ink") === "fg" ? "--slider-range-bg: var(--foreground);" : ""}`,
                    },
                    [h(Slider, { modelValue: v.value, "onUpdate:modelValue": (x: number[]) => (v.value = x), min: 0, max: 100, "aria-label": "Direction", "data-witness": "slider" })],
                ),
            ]);
    }),

    fourier: defineComponent(() => {
        const label = ref(true);
        return () =>
            h("header", { "data-witness": "header", style: "display:flex;justify-content:center;padding:8px 10px" }, [
                h(
                    GlassDock,
                    { orientation: "horizontal", shape: "pill", collapse: false, "data-witness": "dock", ref: (d: unknown) => (w.__dock = d) },
                    {
                        default: () => [
                            h(Popover, null, () => [
                                h(DockTrigger, { for: "popover", "aria-label": "About" }, () => h("span", { style: "font-size:1.5rem;line-height:1" }, "ℱ")),
                                h(PopoverContent, null, () => "about"),
                            ]),
                            h(DockSeparator),
                            h(DropdownMenu, { modal: false }, () => [
                                h(DockTrigger, { for: "dropdown", "aria-label": "Sections" }, () => [
                                    glyph(),
                                    label.value ? h("span", "Equation") : null,
                                    h("svg", { viewBox: "0 0 24 24", width: 16, height: 16, "aria-hidden": "true" }, [h("path", { d: "M6 9l6 6 6-6", fill: "none", stroke: "currentColor" })]),
                                ]),
                                h(DropdownMenuContent, { align: "start" }, () => ["Equation", "Paper", "Gallery"].map((t) => h(DropdownMenuItem, null, () => [glyph(), h("span", t)]))),
                            ]),
                            h(DockSeparator),
                            icon("Sign in", 1),
                            icon("Share", 2),
                            h(DockSeparator),
                            h(DarkModeToggle),
                        ],
                    },
                ),
            ]);
    }),
};

// `wrap`: a consumer's undeclared wrapper around a current anchor (the RouterLink shape the open seat's
// `:has()` arm names), beside two icon seats.
scenes.wrap = defineComponent(() => () =>
    h("div", { style: "display:flex;justify-content:center;align-items:flex-start;padding:16px 0;min-block-size:200px" }, [
        h(GlassDock, { fitContent: true, collapse: false }, {
            collapsed: () => h("span", glyph()),
            default: () => [
                h("span", { "data-witness": "wrap", style: "display:inline-flex" }, h("a", { href: "#home", "aria-current": "page", class: "dock-tab-button", style: "display:inline-flex;align-items:center;gap:4px;padding:0 12px" }, [glyph(), h("span", "Home")])),
                icon("A", 1),
                icon("B", 2),
            ],
        }),
    ]),
);

const Scene = scenes[scene];
if (!Scene) throw new Error(`unknown scene "${scene}"`);
// G10: trace the dock's box from the first frame it exists, every animation frame, for 1.5 s.
const trace: [number, string][] = [];
w.__trace = trace;
const t0 = performance.now();
const tick = () => {
    const d = document.querySelector(".glass-dock");
    const r = d?.getBoundingClientRect();
    const s = r ? `${r.left.toFixed(2)},${r.width.toFixed(2)}x${r.height.toFixed(2)}` : "none";
    if (!trace.length || trace[trace.length - 1]![1] !== s) trace.push([Math.round(performance.now() - t0), s]);
    if (performance.now() - t0 < 1500) requestAnimationFrame(tick);
};
requestAnimationFrame(tick);
createApp(Scene).mount("#app");
w.__ready = true;
